(async () => {
  try {
    const hasCrawler = typeof window.TuquetCrawler !== 'undefined';
    const methods = hasCrawler ? Object.keys(window.TuquetCrawler) : [];
    let crawlResult = null;
    if (hasCrawler) {
      crawlResult = await window.TuquetCrawler.crawlDocument(document, {
        autoDismissModals: false,
        autoScroll: false,
        extractMetadata: true,
        extractMainContent: true,
        toMarkdown: true,
      });
    }
    console.log('[TuquetCrawler Test Result]', {
      hasCrawler,
      methodsCount: methods.length,
      pageType: crawlResult?.pageType,
      title: crawlResult?.metadata?.title,
      markdownLength: crawlResult?.markdown?.length,
    });
    automaNextBlock({
      hasCrawler,
      methodsCount: methods.length,
      pageType: crawlResult?.pageType,
      title: crawlResult?.metadata?.title,
      markdown: crawlResult?.markdown,
    });
  } catch (err) {
    console.error('[TuquetCrawler Error]', err);
    automaNextBlock({ $error: true, message: err.message });
  }
})();
